<template>
  <!--Can't use component for router-link, it does not set the href attribute.
    Surprisingly, it open the link, but it prevents user to open it in a new tab -->
  <router-link v-if="to" :to="to" class="toolbox-button" :rel="rel">
    <span class="toolbox-button-icon">
      <slot name="icon">
        <fa-icon v-if="icon" :icon="icon" fixed-width :class="iconClass" />
      </slot>
    </span>
    <span>
      {{ $filters.uppercaseFirstLetter(label) }}
    </span>
  </router-link>
  <!-- disabled: shown with why (title), not clickable -->
  <component
    v-else
    :is="href ? 'a' : 'div'"
    @click="disabled || $emit('click')"
    :href="disabled ? undefined : href"
    :title="title ?? undefined"
    :aria-disabled="disabled || undefined"
    class="toolbox-button"
    :class="{ 'is-disabled': disabled }"
  >
    <span class="toolbox-button-icon">
      <slot name="icon">
        <fa-icon v-if="icon" :icon="icon" fixed-width :class="iconClass" />
      </slot>
    </span>
    <span>
      {{ $filters.uppercaseFirstLetter(label) }}
    </span>
  </component>
</template>

<script setup lang="ts">
defineProps({
  icon: {
    type: [String, Array],
    default: null,
  },
  iconClass: {
    type: String,
    default: null,
  },
  label: {
    type: String,
    required: true,
  },
  href: {
    type: String,
    default: null,
  },
  rel: {
    type: String,
    default: null,
  },
  disabled: {
    type: Boolean,
    default: false,
  },
  title: {
    type: String,
    default: null,
  },
  to: {
    type: Object,
    default: null,
  },
});
defineEmits(['click']);
</script>

<style scoped>
.toolbox-button {
  display: block;
  cursor: pointer;

  &.is-disabled {
    cursor: not-allowed;
    opacity: 0.5;
  }

  span {
    color: var(--c2c-link);
  }

  :hover {
    color: var(--c2c-text);
  }

  .toolbox-button-icon {
    width: 1rem;
    color: var(--c2c-text);
  }
}
</style>
